package com.edgecloud.device.repository;
import com.edgecloud.device.entity.DeviceTag; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository;
public interface DeviceTagRepository extends JpaRepository<DeviceTag,UUID>{List<DeviceTag> findByProjectIdAndNameContainingIgnoreCaseOrderByNameAsc(UUID projectId,String search);boolean existsByProjectIdAndNormalisedName(UUID projectId,String name);boolean existsByProjectIdAndNormalisedNameAndIdNot(UUID projectId,String name,UUID id);Optional<DeviceTag> findByIdAndProjectId(UUID id,UUID projectId);List<DeviceTag> findAllByIdInAndProjectId(Collection<UUID> ids,UUID projectId);default List<DeviceTag> findAllByIdInAndProject(Collection<UUID> ids,UUID projectId){return ids.isEmpty()?List.of():findAllByIdInAndProjectId(ids,projectId);}}
